using FluentAssertions; using NSubstitute; using VetCommission.Application.Common.Errors; using VetCommission.Application.Common.Results; using VetCommission.Application.Features.Auth.Tenant; using VetCommission.Application.Features.Procedures;
namespace VetCommission.UnitTests.Application.Procedures;
public sealed class ProcedureHandlersTests{[Fact]public async Task List_UsesTenantAndClinic(){var t=Guid.NewGuid();var c=Guid.NewGuid();var repo=Substitute.For<IProcedureRepository>();repo.ListAsync(t,c,1,20,null,null,Arg.Any<CancellationToken>()).Returns(new PagedResult<ProcedureDto>([New(t,c)],1,20,1));var r=await new ProcedureHandlers(repo,new Tenant(t),new Clinic(c)).Handle(new ListProceduresQuery(),CancellationToken.None);r.IsSuccess.Should().BeTrue();await repo.Received(1).ListAsync(t,c,1,20,null,null,Arg.Any<CancellationToken>());} [Fact]public async Task Save_RejectsMissingContext(){var r=await new ProcedureHandlers(Substitute.For<IProcedureRepository>(),new Tenant(null),new Clinic(null)).Handle(new SaveProcedureCommand(null,Guid.NewGuid(),null,"Consulta",null,100),CancellationToken.None);r.Errors.Should().ContainSingle(x=>x.Code==ErrorCodes.Forbidden);} [Fact]public async Task Get_ReturnsNotFound(){var repo=Substitute.For<IProcedureRepository>();repo.GetAsync(Arg.Any<Guid>(),Arg.Any<Guid>(),Arg.Any<Guid>(),Arg.Any<CancellationToken>()).Returns((ProcedureDto?)null);var r=await new ProcedureHandlers(repo,new Tenant(Guid.NewGuid()),new Clinic(Guid.NewGuid())).Handle(new GetProcedureQuery(Guid.NewGuid()),CancellationToken.None);r.Errors.Should().ContainSingle(x=>x.Code==ErrorCodes.NotFound);}static ProcedureDto New(Guid t,Guid c)=>new(Guid.NewGuid(),t,c,Guid.NewGuid(),"C1","Consulta",null,100,true);sealed class Tenant(Guid? x):ITenantContext{public Guid? TenantId=>x;}sealed class Clinic(Guid? x):IClinicContext{public Guid? ClinicId=>x;}}
